function validate(input) {
  const [{ Keywords = [], Posts = [] }] = input;
  const pairs = new Set(), posts = new Set();
  for (const [topic, word] of Keywords) {
    if (topic === null || word === null) return 'Keywords rows may not contain null.';
    if (!/^[A-Za-z]+$/.test(word)) return `Keyword "${word}" must be one word of English letters.`;
    const key = `${topic}|${word.toLowerCase()}`;
    if (pairs.has(key)) return `Topic ${topic} lists the word ${word} twice.`;
    pairs.add(key);
  }
  for (const [id, content] of Posts) {
    if (id === null || content === null) return 'Posts rows may not contain null.';
    if (posts.has(id)) return `post_id ${id} appears twice in Posts.`;
    if (!/^[A-Za-z]+( [A-Za-z]+)*$/.test(content)) return `Post ${id} must be words of English letters separated by single spaces.`;
    posts.add(id);
  }
  return null;
}

