function generate(rand, size) {
  const small = size === 'small';
  const keywords = ['war', 'ball', 'football', 'handball', 'vaccine', 'peace', 'goal', 'virus', 'game', 'sun'];
  // Near misses share letters with keywords but are different words; fillers never match.
  const others = ['warning', 'wars', 'balls', 'footballer', 'vaccinated', 'goals', 'we', 'play', 'the', 'love', 'sunny', 'and'];
  const vocabulary = [...keywords, ...keywords, ...others];
  const caseOf = w => { const r = rand(); return r < 0.15 ? w.toUpperCase() : r < 0.3 ? w[0].toUpperCase() + w.slice(1) : w; };
  const topics = small ? 4 : 30, keywordRows = small ? Math.floor(rand() * 7) : 60, postRows = small ? Math.floor(rand() * 6) : 1500;
  const Keywords = [], seen = new Set();
  for (let i = 0; i < keywordRows * 2 && Keywords.length < keywordRows; i++) {
    const topic = 1 + Math.floor(rand() * topics), word = keywords[Math.floor(rand() * keywords.length)];
    if (seen.has(`${topic}|${word}`)) continue;
    seen.add(`${topic}|${word}`);
    Keywords.push([topic, caseOf(word)]);
  }
  const Posts = [];
  for (let id = 1; id <= postRows; id++) {
    const words = [];
    for (let n = 1 + Math.floor(rand() * (small ? 4 : 8)); n > 0; n--) words.push(caseOf(vocabulary[Math.floor(rand() * vocabulary.length)]));
    Posts.push([id, words.join(' ')]);
  }
  return [{ Keywords, Posts }];
}
